const createEffect = () => {
    const effect = new LensFlareEffect(device);
    effects.push(effect);
    return effect;
};

const makeCameraComponent = (options = {}) => {
    let projectionMatrix;
    if (options.orthographic) {
        projectionMatrix = new Mat4();
    } else {
        // a simple projection whose w is -z, sufficient to produce NDC and clip depth
        projectionMatrix = new Mat4();
        projectionMatrix.data[11] = -1;
        projectionMatrix.data[15] = 0;
    }

    const position = options.position ?? new Vec3(0, 0, 0);
    const camera = {
        viewMatrix: options.viewMatrix ?? new Mat4(),
        projectionMatrix: options.projectionMatrix ?? projectionMatrix,
        farClip: options.farClip ?? 100,
        projection: options.orthographic ? PROJECTION_ORTHOGRAPHIC : PROJECTION_PERSPECTIVE
    };

    return {
        camera,
        entity: {
            getPosition: () => position
        },
        shaderParams: {},
        system: {
            app: {
                scene: {
                    physicalUnits: !!options.physicalUnits
                }
            }
        }
    };
};

const attachFrameAndCreatePass = (effect, cameraComponent = makeCameraComponent()) => {
    const cameraFrame = {
        cameraComponent,
        hdrFormat: 'hdrFormat',
        removeEffect: jest.fn(() => {
            effect.cameraFrame = null;
        })
    };
    effect.cameraFrame = cameraFrame;

    const passes = { postResolve: [] };
    effect.createPasses({ depth: { texture: 'depthTexture' } }, passes);
    return { cameraFrame, passes, pass: passes.postResolve[0] };
};

const makeShapeLibrary = () => ({
    shapes: {
        glow: { texture: 'glowTexture' },
        star: { texture: 'starTexture' },
        disc: { texture: 'discTexture' }
    }
});

const readTextureData = (texture) => {
    const data = texture.lock({ mode: TEXTURELOCK_READ });
    const copy = Array.from(data);
    texture.unlock();
    return copy;
};

const makeLight = (options = {}) => ({
