describe('GltfExporter.writeBufferView', () => {
    test('writes one aligned buffer view per element of a non-interleaved vertex buffer', () => {
        const vertexBuffer = makeVertexBuffer({
            numVertices: 2,
            interleaved: false,
            elements: [
                { name: SEMANTIC_POSITION, offset: 0, size: 12, dataType: TYPE_FLOAT32, numComponents: 3 },
                { name: SEMANTIC_NORMAL, offset: 24, size: 12, dataType: TYPE_FLOAT32, numComponents: 3 }
            ],
            data: new Float32Array(12)
        });
        const resources = makeResources();
        const json = { bufferViews: [] };

        GltfExporter.writeBufferView(resources, json, vertexBuffer);

        expect(json.bufferViews).toEqual([
            { buffer: 0, byteLength: 24, byteOffset: 0, target: 34962, byteStride: 12 },
            { buffer: 0, byteLength: 24, byteOffset: 24, target: 34962, byteStride: 12 }
        ]);
        expect(json.buffers).toEqual([{ byteLength: 48 }]);
        expect(resources.bufferViewMap.get(vertexBuffer)).toEqual([0, 1]);
    });

    test('writes a single strided view for an interleaved vertex buffer', () => {
        const resources = makeResources();
        const json = { bufferViews: [] };
        const vertexBuffer = makeVertexBuffer({
            numVertices: 2,
            interleaved: true,
            elements: [
                { name: SEMANTIC_POSITION, offset: 0, size: 12, dataType: TYPE_FLOAT32, numComponents: 3 },
                { name: SEMANTIC_TEXCOORD0, offset: 12, size: 8, dataType: TYPE_FLOAT32, numComponents: 2 }
            ],
            size: 20,
            data: new Float32Array(10)
        });

        GltfExporter.writeBufferView(resources, json, vertexBuffer);

        expect(json.bufferViews).toEqual([
            { buffer: 0, byteLength: 40, byteOffset: 0, target: 34962, byteStride: 20 }
        ]);
        expect(resources.bufferViewMap.get(vertexBuffer)).toEqual([0]);
    });

    test('writes index buffers and pads subsequent raw buffers to four-byte alignment', () => {
        const resources = makeResources();
        const json = { bufferViews: [] };
        const indexBuffer = makeIndexBuffer(INDEXFORMAT_UINT16, new Uint16Array([0, 1, 2]));
        const raw = new Uint8Array([1, 2, 3, 4, 5]).buffer;

        GltfExporter.writeBufferView(resources, json, indexBuffer);
        GltfExporter.writeBufferView(resources, json, raw);

        expect(json.bufferViews).toEqual([
            { buffer: 0, byteLength: 6, byteOffset: 0, target: 34963 },
            { buffer: 0, byteLength: 5, byteOffset: 8 }
        ]);
        expect(json.buffers).toEqual([{ byteLength: 13 }]);
        expect(resources.bufferViewMap.get(indexBuffer)).toEqual([0]);
        expect(resources.bufferViewMap.get(raw)).toEqual([1]);
    });
});

