                ]
            }]
        });
        const json = { bufferViews: [], buffers: [{ byteLength: 0 }] };

        new GltfExporter().writeMeshes(resources, json, {});

        expect(json.accessors).toHaveLength(4);
        expect(json.accessors[0]).toMatchObject({
            componentType: 5126,
            type: 'VEC3',
            count: 3,
            min: [0, 0, 0],
            max: [1, 1, 0]
        });
        expect(json.accessors[1]).toEqual({
            bufferView: 1,
            componentType: 5123,
            count: 3,
            type: 'SCALAR'
        });
        expect(json.meshes).toHaveLength(1);
        expect(json.accessors[2]).toMatchObject({ bufferView: 0, componentType: 5126, type: 'VEC3' });
        expect(json.accessors[3]).toEqual({ bufferView: 1, componentType: 5123, count: 3, type: 'SCALAR' });
        expect(json.meshes[0].primitives).toEqual([
            { attributes: { POSITION: 0 }, indices: 1, material: 1 },
            { attributes: { POSITION: 2 }, indices: 3, material: 0 }
        ]);
    });

    test.each([
        [INDEXFORMAT_UINT8, new Uint8Array([0, 1, 2]), 5121],
        [INDEXFORMAT_UINT16, new Uint16Array([0, 1, 2]), 5123],
        [INDEXFORMAT_UINT32, new Uint32Array([0, 1, 2]), 5125]
    ])('maps index format %# to component type %i', (format, data, componentType) => {
        const vertexBuffer = makeVertexBuffer({
            elements: [{ name: SEMANTIC_POSITION, offset: 0, size: 12, dataType: TYPE_FLOAT32, numComponents: 3 }],
            data: new Float32Array(9)
        });
        const indexBuffer = makeIndexBuffer(format, data);
