        expect(json.buffers[0].byteLength).toBe(128);
        expect(resources.buffers).toHaveLength(1);
        expect(Object.prototype.toString.call(resources.buffers[0])).toBe('[object ArrayBuffer]');
        expect(resources.buffers[0].byteLength).toBe(128);
    });
});

describe('GltfExporter texture encoding helpers', () => {
    class MemoryFileReader {
        readAsArrayBuffer(blob) {
            blob.arrayBuffer().then((result) => {
                this.result = result;
                this.onloadend();
            });
        }
    }

    test('writeTextures picks JPEG only for collected opaque canvases and emits image, sampler and texture data', async () => {
        const originalFileReader = Object.getOwnPropertyDescriptor(globalThis, 'FileReader');
        Object.defineProperty(globalThis, 'FileReader', {
            configurable: true,
            writable: true,
            value: MemoryFileReader
        });
        try {
            const exporter = new GltfExporter();
            const compressible = { minFilter: FILTER_LINEAR_MIPMAP_LINEAR, magFilter: FILTER_LINEAR, addressU: ADDRESS_REPEAT, addressV: ADDRESS_MIRRORED_REPEAT };
            const nonCompressible = { minFilter: FILTER_NEAREST, magFilter: FILTER_NEAREST, addressU: ADDRESS_CLAMP_TO_EDGE, addressV: ADDRESS_CLAMP_TO_EDGE };
            const transparent = { minFilter: FILTER_LINEAR_MIPMAP_LINEAR, magFilter: FILTER_LINEAR, addressU: ADDRESS_REPEAT, addressV: ADDRESS_REPEAT };
            const resources = makeResources({
                textures: [compressible, nonCompressible, transparent],
                compressibleTexture: new Set([compressible, transparent])
            });
            const json = { images: [], samplers: [], textures: [], bufferViews: [], buffers: [{ byteLength: 0 }] };
            const opaqueCanvas = {
                width: 1,
                height: 1,
                getContext: () => ({ getImageData: () => ({ data: new Uint8ClampedArray([1, 2, 3, 255]) }) })
            };
            const transparentCanvas = {
                width: 1,
                height: 1,
                getContext: () => ({ getImageData: () => ({ data: new Uint8ClampedArray([1, 2, 3, 0]) }) })
            };
            const blobs = [];
            jest.spyOn(exporter, 'getBlob').mockImplementation((canvas, mimeType) => {
                blobs.push(mimeType);
                return Promise.resolve(new Blob([new Uint8Array([1, 2, 3])], { type: mimeType }));
            });

            await exporter.writeTextures(resources, [opaqueCanvas, opaqueCanvas, transparentCanvas], json, {});

            expect(blobs).toEqual(['image/jpeg', 'image/png', 'image/png']);
            expect(json.images).toEqual([
                { mimeType: 'image/jpeg', bufferView: 0 },
                { mimeType: 'image/png', bufferView: 1 },
                { mimeType: 'image/png', bufferView: 2 }
            ]);
            expect(json.samplers[0]).toEqual({
                minFilter: 9987,
                magFilter: 9729,
                wrapS: 10497,
                wrapT: 33648
            });
            expect(json.samplers[1]).toEqual({
                minFilter: 9728,
                magFilter: 9728,
                wrapS: 33071,
                wrapT: 33071
            });
            expect(json.textures).toEqual([
                { sampler: 0, source: 0 },
                { sampler: 1, source: 1 },
                { sampler: 2, source: 2 }
            ]);
            expect(json.bufferViews.every(view => view.byteLength === 4)).toBe(true);
