describe('GltfExporter texture encoding helpers', () => {
    class MemoryFileReader {
        readAsArrayBuffer(blob) {
            blob.arrayBuffer().then((result) => {
                this.result = result;
                this.onloadend();
            });
        }
    }

    test('writeTextures picks JPEG only for collected opaque canvases and emits image, sampler and texture data', async () => {
        const originalFileReader = Object.getOwnPropertyDescriptor(globalThis, 'FileReader');
        Object.defineProperty(globalThis, 'FileReader', {
            configurable: true,
            writable: true,
            value: MemoryFileReader
        });
        try {
            const exporter = new GltfExporter();
            const compressible = { minFilter: FILTER_LINEAR_MIPMAP_LINEAR, magFilter: FILTER_LINEAR, addressU: ADDRESS_REPEAT, addressV: ADDRESS_MIRRORED_REPEAT };
            const nonCompressible = { minFilter: FILTER_NEAREST, magFilter: FILTER_NEAREST, addressU: ADDRESS_CLAMP_TO_EDGE, addressV: ADDRESS_CLAMP_TO_EDGE };
            const transparent = { minFilter: FILTER_LINEAR_MIPMAP_LINEAR, magFilter: FILTER_LINEAR, addressU: ADDRESS_REPEAT, addressV: ADDRESS_REPEAT };
            const resources = makeResources({
                textures: [compressible, nonCompressible, transparent],
                compressibleTexture: new Set([compressible, transparent])
            });
            const json = { images: [], samplers: [], textures: [], bufferViews: [], buffers: [{ byteLength: 0 }] };
            const opaqueCanvas = {
                width: 1,
                height: 1,
                getContext: () => ({ getImageData: () => ({ data: new Uint8ClampedArray([1, 2, 3, 255]) }) })
            };
            const transparentCanvas = {
                width: 1,
                height: 1,
                getContext: () => ({ getImageData: () => ({ data: new Uint8ClampedArray([1, 2, 3, 0]) }) })
            };
            const blobs = [];
            jest.spyOn(exporter, 'getBlob').mockImplementation((canvas, mimeType) => {
                blobs.push(mimeType);
                return Promise.resolve(new Blob([new Uint8Array([1, 2, 3])], { type: mimeType }));
            });

            await exporter.writeTextures(resources, [opaqueCanvas, opaqueCanvas, transparentCanvas], json, {});

            expect(blobs).toEqual(['image/jpeg', 'image/png', 'image/png']);
            expect(json.images).toEqual([
                { mimeType: 'image/jpeg', bufferView: 0 },
                { mimeType: 'image/png', bufferView: 1 },
                { mimeType: 'image/png', bufferView: 2 }
            ]);
            expect(json.samplers[0]).toEqual({
                minFilter: 9987,
                magFilter: 9729,
                wrapS: 10497,
                wrapT: 33648
            });
            expect(json.samplers[1]).toEqual({
                minFilter: 9728,
                magFilter: 9728,
                wrapS: 33071,
                wrapT: 33071
            });
            expect(json.textures).toEqual([
                { sampler: 0, source: 0 },
                { sampler: 1, source: 1 },
                { sampler: 2, source: 2 }
            ]);
            expect(json.bufferViews.every(view => view.byteLength === 4)).toBe(true);
        } finally {
            if (originalFileReader) {
                Object.defineProperty(globalThis, 'FileReader', originalFileReader);
            } else {
                delete globalThis.FileReader;
            }
        }
    });

    test('convertTextures forwards maxTextureSize and preserves source order', async () => {
        const exporter = new GltfExporter();
        const calls = [];
        jest.spyOn(exporter, 'textureToCanvas').mockImplementation((texture, options) => {
            calls.push([texture, options]);
            return Promise.resolve(`${texture.name}-canvas`);
        });
        const a = { name: 'a' };
        const b = { name: 'b' };

        const promises = exporter.convertTextures([a, b], { maxTextureSize: 256 });

        expect(promises).toHaveLength(2);
        await expect(Promise.all(promises)).resolves.toEqual(['a-canvas', 'b-canvas']);
        expect(calls).toEqual([[a, { maxTextureSize: 256 }], [b, { maxTextureSize: 256 }]]);
    });

    test('getBlob uses canvas.toBlob when available', async () => {
        const canvas = {
            toBlob: jest.fn(callback => callback('blob-result'))
        };

        await expect(new GltfExporter().getBlob(canvas, 'image/png')).resolves.toBe('blob-result');
        expect(canvas.toBlob).toHaveBeenCalledWith(expect.any(Function), 'image/png');
    });

    test.each([
        ['image/png', 1.0],
        ['image/jpeg', 0.92]
    ])('getBlob falls back to convertToBlob for %s with quality %s', async (mimeType, quality) => {
        const canvas = {
            convertToBlob: jest.fn(options => Promise.resolve(options))
        };

        await expect(new GltfExporter().getBlob(canvas, mimeType)).resolves.toEqual({ type: mimeType, quality });
        expect(canvas.convertToBlob).toHaveBeenCalledWith({ type: mimeType, quality });
    });

    test('getPaddedArrayBuffer returns aligned buffers unchanged and pads others without mutating the source', () => {
        const exporter = new GltfExporter();
        const aligned = new Uint8Array([1, 2, 3, 4]).buffer;
        const unaligned = new Uint8Array([5, 6, 7]).buffer;
        const original = new Uint8Array(unaligned.slice(0));

        expect(exporter.getPaddedArrayBuffer(aligned)).toBe(aligned);
        const padded = exporter.getPaddedArrayBuffer(unaligned);
        expect(padded).not.toBe(unaligned);
        expect(new Uint8Array(padded)).toEqual(new Uint8Array([5, 6, 7, 0]));
        expect(new Uint8Array(unaligned)).toEqual(original);
        expect(new Uint8Array(exporter.getPaddedArrayBuffer(unaligned, 9))).toEqual(new Uint8Array([5, 6, 7, 9]));
    });
});

describe('GltfExporter.buildJson and build', () => {
    test('buildJson produces the base glTF document and removes empty texture collections', async () => {
        const json = await new GltfExporter().buildJson(makeResources(), {});

        expect(json).toEqual({
            asset: {
                version: '2.0',
                generator: 'PlayCanvas GltfExporter'
            },
            scenes: [{ nodes: [0] }],
            scene: 0,
            bufferViews: []
        });
    });

    test('build emits a valid GLB header, JSON chunk and binary chunk', async () => {
        const exporter = new GltfExporter();
        const positions = [0, 0, 0, 2, 0, 0, 0, 2, 0];
        const vertexBuffer = makeVertexBuffer({
            numVertices: 3,
            elements: [
                { name: SEMANTIC_POSITION, offset: 0, size: 12, dataType: TYPE_FLOAT32, numComponents: 3 }
            ],
            data: new Float32Array(positions)
        });
        const indexBuffer = makeIndexBuffer(INDEXFORMAT_UINT16, new Uint16Array([0, 1, 2]));
        const mesh = makeMesh({ vertexBuffer, indexBuffer, positions });
        const material = { name: 'Triangle', blendType: BLEND_NONE, cull: 1, alphaTest: 0, aoIntensity: 1 };
        const node = makeEntity({ name: 'TriangleNode' });
        node.render = {
            enabled: true,
            meshInstances: [{ material, node, mesh }]
        };
        const root = makeEntity({ name: 'Root', children: [node] });

        const glb = await exporter.build(root);
        const view = new DataView(glb);

        expect(view.getUint32(0, true)).toBe(0x46546c67);
        expect(view.getUint32(4, true)).toBe(2);
        expect(view.getUint32(8, true)).toBe(glb.byteLength);

        const jsonLength = view.getUint32(12, true);
        expect(view.getUint32(16, true)).toBe(0x4e4f534a);
        const jsonText = new TextDecoder().decode(new Uint8Array(glb, 20, jsonLength));
        const json = JSON.parse(jsonText);
        expect(json.asset).toEqual({ version: '2.0', generator: 'PlayCanvas GltfExporter' });
        expect(json.nodes.map(n => n.name)).toEqual(['Root', 'TriangleNode']);
        expect(json.nodes[1].mesh).toBe(0);
        expect(json.meshes[0].primitives[0].material).toBe(0);
        expect(json.accessors[0]).toMatchObject({ componentType: 5126, type: 'VEC3', count: 3, min: [0, 0, 0], max: [2, 2, 0] });

        const binHeaderOffset = 20 + jsonLength;
        expect(view.getUint32(binHeaderOffset, true)).toBe(math.roundUp(json.buffers[0].byteLength, 4));
        expect(view.getUint32(binHeaderOffset + 4, true)).toBe(0x004e4942);
        const binaryLength = view.getUint32(binHeaderOffset, true);
        expect(binHeaderOffset + 8 + binaryLength).toBe(glb.byteLength);
        const binary = new Uint8Array(glb, binHeaderOffset + 8, binaryLength);
        expect(Array.from(new Uint16Array(binary.buffer.slice(binary.byteOffset + 36, binary.byteOffset + 42)))).toEqual([0, 1, 2]);
    });
});

