describe('initializeComponentData options', () => {
    test('applies enabled, useInput, fitMode, batchGroupId and copies layers', () => {
        const entity = new Entity('element', app);
        const layers = [1, 2];

        const component = system.addComponent(entity, {
            enabled: false,
            useInput: false,
            fitMode: FITMODE_CONTAIN,
            batchGroupId: 5,
            layers
        });

        expect(component.enabled).toBe(false);
        expect(component.useInput).toBe(false);
        expect(component.fitMode).toBe(FITMODE_CONTAIN);
        expect(component.batchGroupId).toBe(5);
        expect(component.layers).toEqual([1, 2]);
        expect(component.layers).not.toBe(layers);

        layers.push(3);
        expect(component.layers).toEqual([1, 2]);
    });

    test('defaults batchGroupId to -1 when it is absent or null', () => {
        const absentEntity = new Entity('absent', app);
        const nullEntity = new Entity('null', app);
        const setEntity = new Entity('set', app);

        const absent = system.addComponent(absentEntity, {});
        const nulled = system.addComponent(nullEntity, { batchGroupId: null });
        const set = system.addComponent(setEntity, { batchGroupId: 0 });

        expect(absent.batchGroupId).toBe(-1);
        expect(nulled.batchGroupId).toBe(-1);
        expect(set.batchGroupId).toBe(0);
    });

    test('enables the component by default and calls onEnable', () => {
        const entity = new Entity('element', app);
        entity._enabledInHierarchy = true;
        const onEnable = jest.spyOn(ElementComponent.prototype, 'onEnable');

        const component = system.addComponent(entity, {});

        expect(component.enabled).toBe(true);
        expect(onEnable).toHaveBeenCalledTimes(1);
        expect(onEnable.mock.instances[0]).toBe(component);

        onEnable.mockRestore();
    });
});

