    describe('destroy and loseContext', () => {
        test('deletes the GL texture and clears it from every texture unit slot', () => {
            const device = createDevice();
            const other = { other: true };
            const glTexture = { glTexture: true };
            device.textureUnits = [
                [glTexture, other, glTexture],
                [other, glTexture],
                [null]
            ];
            const impl = new WebglTexture(createStubTexture());
            impl._glTexture = glTexture;

            impl.destroy(device);

            expect(device.gl.deleteTexture).toHaveBeenCalledTimes(1);
            expect(device.gl.deleteTexture).toHaveBeenCalledWith(glTexture);
            expect(impl._glTexture).toBeNull();
            expect(device.textureUnits).toEqual([
                [null, other, null],
                [other, null],
                [null]
            ]);
        });

        test('does nothing when there is no GL texture', () => {
            const device = createDevice();
            device.textureUnits = [[{ untouched: true }]];
            const impl = new WebglTexture(createStubTexture());
            impl._glTexture = null;

            impl.destroy(device);
            impl.destroy(device);

            expect(device.gl.deleteTexture).not.toHaveBeenCalled();
            expect(device.textureUnits).toEqual([[{ untouched: true }]]);
            expect(impl._glTexture).toBeNull();
        });

        test('loseContext drops the GL texture reference without deleting or unbinding it', () => {
            const device = createDevice();
            const glTexture = { glTexture: true };
            device.textureUnits = [[glTexture]];
            const impl = new WebglTexture(createStubTexture());
            impl._glTexture = glTexture;

            impl.loseContext();

            expect(impl._glTexture).toBeNull();
            expect(device.gl.deleteTexture).not.toHaveBeenCalled();
            expect(device.textureUnits).toEqual([[glTexture]]);
        });
    });

