    describe('read, write and copy', () => {
        test('read delegates to the device texture read operation', () => {
            const readTextureAsync = jest.fn(() => 'read-result');
            const texture = { device: { readTextureAsync } };
            const impl = new WebglTexture(texture);
            const options = { mipLevel: 2, face: 3 };

            expect(impl.read(1, 2, 3, 4, options)).toBe('read-result');
            expect(readTextureAsync).toHaveBeenCalledWith(texture, 1, 2, 3, 4, options);
        });

        test('write binds the texture before delegating to the write operation', () => {
            const setTexture = jest.fn();
            const writeTextureAsync = jest.fn(() => 'write-result');
            const texture = { device: { setTexture, writeTextureAsync } };
            const impl = new WebglTexture(texture);
            const data = new Uint8Array(4);

            expect(impl.write(5, 6, 7, 8, data)).toBe('write-result');
            expect(setTexture).toHaveBeenCalledWith(texture, 0);
            expect(writeTextureAsync).toHaveBeenCalledWith(texture, 5, 6, 7, 8, data);
            expect(setTexture.mock.invocationCallOrder[0]).toBeLessThan(writeTextureAsync.mock.invocationCallOrder[0]);
        });

        test('copy delegates to the device texture copy operation', () => {
            const copyTextureToTexture = jest.fn(() => true);
            const texture = { device: { copyTextureToTexture } };
            const source = { name: 'source' };
            const options = { sourceMipLevel: 1 };
            const impl = new WebglTexture(texture);

            expect(impl.copy(source, options)).toBe(true);
            expect(copyTextureToTexture).toHaveBeenCalledWith(source, texture, options);
        });
    });

