    });
});

describe('GSplatProjector#dispatch', () => {
    test('allocates projection buffers and supplies camera, viewport and culling uniforms', () => {
        const workBuffer = createWorkBuffer({ textures: { stream0: { kind: 'stream0Texture' } } });
        const cameraNode = createCameraNode();
        const params = dispatchParams(workBuffer, cameraNode);
        const clearSpy = jest.spyOn(projector.renderCounter, 'clear');
        const weightsSpy = jest.spyOn(projector.binWeightsBuffer, 'write');

        projector.dispatch(params);

        // Buffers are sized to the work-buffer capacity, not the visible count.
        expect(projector.projCache).not.toBeNull();
        expect(projector.projCache.byteSize).toBe(100 * CACHE_STRIDE * 4);
        expect(projector.projCache.name).toBe('GsplatProjector.projCache');
        expect(projector.sortKeys).not.toBeNull();
        expect(projector.sortKeys.byteSize).toBe(100 * 4);
        expect(projector.sortKeys.name).toBe('GsplatProjector.sortKeys');

        // The counter is reset once for the pass, and the bin weights are uploaded.
        expect(clearSpy).toHaveBeenCalledTimes(1);
        expect(weightsSpy).toHaveBeenCalledTimes(1);
        expect(weightsSpy.mock.calls[0][0]).toBe(0);
        expect(weightsSpy.mock.calls[0][1]).toBeInstanceOf(Float32Array);
        expect(weightsSpy.mock.calls[0][1]).toHaveLength(GSplatSortBinWeights.NUM_BINS * 2);

        const compute = lastCompute(device);
        expect(compute).toBe(projector._projectorComputes.get('r'));
        expect(compute.name).toBe('GSplatProjectorRadial');

        expect(compute.getParameter('compactedSplatIds')).toBe(params.compactedSplatIds);
        expect(compute.getParameter('sortElementCount')).toBe(params.sortElementCountBuffer);
        expect(compute.getParameter('projCache')).toBe(projector.projCache);
        expect(compute.getParameter('sortKeys')).toBe(projector.sortKeys);
        expect(compute.getParameter('renderCounter')).toBe(projector.renderCounter);
        expect(compute.getParameter('binWeights')).toBe(projector.binWeightsBuffer);

        expect(Array.from(compute.getParameter('cameraPosition'))).toEqual([1, 2, 3]);
        expect(Array.from(compute.getParameter('cameraDirection'))).toEqual([0, 0, -1]);
        expect(Array.from(compute.getParameter('viewMatrix'))).toEqual(
            Array.from(cameraNode.camera.camera.viewMatrix.data)
        );
        expect(compute.getParameter('viewProj')).toBeInstanceOf(Float32Array);
        expect(compute.getParameter('viewProj')).toHaveLength(16);

        expect(compute.getParameter('focal')).toBeCloseTo(1200);
        expect(compute.getParameter('focalY')).toBeCloseTo(1200);
        expect(compute.getParameter('viewportWidth')).toBe(800);
        expect(compute.getParameter('viewportHeight')).toBe(600);
        expect(compute.getParameter('nearClip')).toBe(0.1);
        expect(compute.getParameter('farClip')).toBe(1000);
        expect(compute.getParameter('alphaClip')).toBe(0.1);
        expect(compute.getParameter('minPixelSize')).toBe(1);
        expect(compute.getParameter('minContribution')).toBe(0.01);
        expect(compute.getParameter('foveationStrength')).toBe(0);
        expect(compute.getParameter('foveationCenter')).toBe(0.3);
        expect(compute.getParameter('isOrtho')).toBe(0);
        expect(compute.getParameter('splatTextureSize')).toBe(128);
        expect(compute.getParameter('numBins')).toBe(GSplatSortBinWeights.NUM_BINS);
        expect(compute.getParameter('minDist')).toBe(0.1);
        expect(compute.getParameter('invRange')).toBeCloseTo(1 / (100 - 0.1));
        expect(compute.getParameter('stochastic')).toBe(0);

        // Stream textures are bound when the work buffer has one; absent streams are skipped.
        expect(compute.getParameter('stream0')).toEqual({ kind: 'stream0Texture' });
        expect(compute.parameters.has('stream1')).toBe(false);

        // A thread per splice of capacity, rounded up to the shader workgroup size.
        expect(compute.countX).toBe(2);
        expect(device.computeDispatch).toHaveBeenCalledWith([compute], 'GSplatProjector');
    });

    test('reuses allocated buffers for the same or a smaller capacity', () => {
        const workBuffer = createWorkBuffer();
        const cameraNode = createCameraNode();

        projector.dispatch(dispatchParams(workBuffer, cameraNode, { totalCapacity: 100 }));
        const cache = projector.projCache;
        const keys = projector.sortKeys;
        const compute = lastCompute(device);
        const cacheDestroy = jest.spyOn(cache, 'destroy');
        const keysDestroy = jest.spyOn(keys, 'destroy');

        projector.dispatch(dispatchParams(workBuffer, cameraNode, { totalCapacity: 100 }));

        expect(projector.projCache).toBe(cache);
        expect(projector.sortKeys).toBe(keys);
        expect(lastCompute(device)).toBe(compute);
        expect(cacheDestroy).not.toHaveBeenCalled();
        expect(keysDestroy).not.toHaveBeenCalled();

        projector.dispatch(dispatchParams(workBuffer, cameraNode, { totalCapacity: 250 }));

        expect(projector.projCache).not.toBe(cache);
        expect(projector.sortKeys).not.toBe(keys);
        expect(cacheDestroy).toHaveBeenCalledTimes(1);
        expect(keysDestroy).toHaveBeenCalledTimes(1);
        expect(projector.projCache.byteSize).toBe(250 * CACHE_STRIDE * 4);
        expect(projector.sortKeys.byteSize).toBe(250 * 4);

        const grownCache = projector.projCache;
        const grownKeys = projector.sortKeys;
        const grownCacheDestroy = jest.spyOn(grownCache, 'destroy');
        const grownKeysDestroy = jest.spyOn(grownKeys, 'destroy');

        projector.dispatch(dispatchParams(workBuffer, cameraNode, { totalCapacity: 50 }));

        // Buffers never shrink, avoiding reallocation when the visible splat count drops.
        expect(projector.projCache).toBe(grownCache);
        expect(projector.sortKeys).toBe(grownKeys);
        expect(grownCacheDestroy).not.toHaveBeenCalled();
        expect(grownKeysDestroy).not.toHaveBeenCalled();
    });

    test('computes camera-relative bin weights for the active sort mode and bit budget', () => {
        const cameraNode = createCameraNode();
        const computeBin = jest.spyOn(projector.binWeightsUtil, 'compute');

        projector.dispatch(dispatchParams(createWorkBuffer(), cameraNode, {
            radialSort: true,
            numBits: 12
        }));
        expect(computeBin).toHaveBeenNthCalledWith(1, GSplatSortBinWeights.NUM_BINS - 1, 1 << 12);

        projector.dispatch(dispatchParams(createWorkBuffer(), cameraNode, {
            radialSort: false,
            numBits: 12
        }));
        // The camera sits at the near end of the linear range, which maps to bin 0.
        expect(computeBin).toHaveBeenNthCalledWith(2, 0, 1 << 12);
    });

    test('forwards explicit foveation settings to the projector uniforms', () => {
        projector.dispatch(dispatchParams(createWorkBuffer(), createCameraNode(), {
            foveationStrength: 0.75,
            foveationCenter: 0.4
        }));

        const compute = lastCompute(device);
        expect(compute.getParameter('foveationStrength')).toBe(0.75);
        expect(compute.getParameter('foveationCenter')).toBe(0.4);
    });

    test('handles orthographic projection and a degenerate depth range', () => {
        const cameraNode = createCameraNode({ projection: PROJECTION_ORTHOGRAPHIC });

        projector.dispatch(dispatchParams(createWorkBuffer(), cameraNode, {
            minDist: 5,
            maxDist: 5
        }));

        const compute = lastCompute(device);
        expect(compute.getParameter('isOrtho')).toBe(1);
        expect(compute.getParameter('invRange')).toBe(1);
    });

    test('sets GSPLAT_COLOR_FLOAT only for non-RGBA16U color streams', () => {
        const cameraNode = createCameraNode();

        projector.dispatch(dispatchParams(createWorkBuffer({ colorFormat: PIXELFORMAT_RGBA16U }), cameraNode));
        const r16Compute = lastCompute(device);
        expect(r16Compute.shader.computeDefinition.cdefines.has('GSPLAT_COLOR_FLOAT')).toBe(false);

        // Force a newly compiled variant for the different stream format.
        projector.dispatch(dispatchParams(
            createWorkBuffer({ version: 2, colorFormat: PIXELFORMAT_RGBA32F }),
            cameraNode
        ));
        const r32Compute = lastCompute(device);
        expect(r32Compute.shader.computeDefinition.cdefines.has('GSPLAT_COLOR_FLOAT')).toBe(true);
    });
});

describe('GSplatProjector variant selection', () => {
    test.each([
        {
            label: 'radial',
            overrides: {},
            key: 'r',
            name: 'GSplatProjectorRadial',
            present: ['RADIAL_SORT'],
            absent: ['PICK_MODE', 'GSPLAT_AA', 'GSPLAT_FISHEYE', 'GSPLAT_XR']
        },
        {
            label: 'linear',
            overrides: { radialSort: false },
            key: 'l',
            name: 'GSplatProjectorLinear',
            present: [],
            absent: ['RADIAL_SORT', 'PICK_MODE', 'GSPLAT_AA', 'GSPLAT_FISHEYE', 'GSPLAT_XR']
        },
        {
            label: 'radial pick',
            overrides: { pickMode: true },
            key: 'rp',
            name: 'GSplatProjectorRadialPick',
            present: ['RADIAL_SORT', 'PICK_MODE'],
            absent: ['GSPLAT_AA', 'GSPLAT_FISHEYE', 'GSPLAT_XR']
        },
        {
            label: 'radial anti-aliased',
            overrides: { antiAlias: true },
            key: 'ra',
            name: 'GSplatProjectorRadialAa',
            present: ['RADIAL_SORT', 'GSPLAT_AA'],
            absent: ['PICK_MODE', 'GSPLAT_FISHEYE', 'GSPLAT_XR']
        },
        {
            label: 'pick mode folds away anti-aliasing',
            overrides: { pickMode: true, antiAlias: true },
            key: 'rp',
            name: 'GSplatProjectorRadialPick',
            present: ['RADIAL_SORT', 'PICK_MODE'],
            absent: ['GSPLAT_AA', 'GSPLAT_FISHEYE', 'GSPLAT_XR']
        },
        {
            label: 'stochastic folds away radial sort',
            overrides: { stochastic: true },
            key: 'l',
            name: 'GSplatProjectorLinear',
            present: [],
            absent: ['RADIAL_SORT', 'PICK_MODE', 'GSPLAT_AA', 'GSPLAT_FISHEYE', 'GSPLAT_XR']
        }
    ])('selects $label variant and matching shader defines', ({ overrides, key, name, present, absent }) => {
        projector.dispatch(dispatchParams(createWorkBuffer(), createCameraNode(), overrides));

        const compute = lastCompute(device);
        expect(compute.name).toBe(name);
        expect(projector._projectorComputes.get(key)).toBe(compute);
        expect(projector._projectorComputes.size).toBe(1);

        const cdefines = compute.shader.computeDefinition.cdefines;
        expect(cdefines.get('{CACHE_STRIDE}')).toBe(String(CACHE_STRIDE));
        present.forEach(define => expect(cdefines.has(define)).toBe(true));
        absent.forEach(define => expect(cdefines.has(define)).toBe(false));
    });

    test('caches compute instances per variant and rebuilds them when the work-buffer format version changes', () => {
        const cameraNode = createCameraNode();
        const params = dispatchParams(createWorkBuffer({ version: 1 }), cameraNode);

        projector.dispatch(params);
        const radial = lastCompute(device);

        projector.dispatch({ ...params, radialSort: false });
        const linear = lastCompute(device);
        expect(linear).not.toBe(radial);
        expect(projector._projectorComputes.size).toBe(2);

        projector.dispatch(params);
        expect(lastCompute(device)).toBe(radial);
        expect(projector._projectorComputes.size).toBe(2);

        const radialDestroy = jest.spyOn(radial, 'destroy');
        const radialShaderDestroy = jest.spyOn(radial.shader, 'destroy');
        const linearDestroy = jest.spyOn(linear, 'destroy');

        projector.dispatch(dispatchParams(createWorkBuffer({ version: 2 }), cameraNode));

        const rebuilt = lastCompute(device);
        expect(rebuilt).not.toBe(radial);
        expect(projector._projectorComputes.size).toBe(1);
        expect(radialDestroy).toHaveBeenCalledTimes(1);
        expect(radialShaderDestroy).toHaveBeenCalledTimes(1);
        expect(linearDestroy).toHaveBeenCalledTimes(1);
    });

    test('skips bin-weight computation and upload when generating stochastic keys', () => {
        const weightsSpy = jest.spyOn(projector.binWeightsBuffer, 'write');
        const computeBin = jest.spyOn(projector.binWeightsUtil, 'compute');

        projector.dispatch(dispatchParams(createWorkBuffer(), createCameraNode(), { stochastic: true }));

        expect(weightsSpy).not.toHaveBeenCalled();
        expect(computeBin).not.toHaveBeenCalled();
        expect(lastCompute(device).getParameter('stochastic')).toBe(1);
    });

    test('asserts that stochastic and pick modes are mutually exclusive', () => {
        const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});

        projector.dispatch(dispatchParams(createWorkBuffer(), createCameraNode(), {
            stochastic: true,
            pickMode: true
        }));

        const text = errorSpy.mock.calls.flat().join(' ');
        expect(text).toContain('stochastic and pickMode are mutually exclusive');
    });
});

describe('GSplatProjector fisheye mode', () => {
