describe('submitCasters', () => {
    function setup(rendererOverrides = {}) {
        const device = createDevice();
        const renderer = createRenderer(device, rendererOverrides);
        const sr = createSr(renderer);
        const camera = { renderTarget: { flipY: false }, shaderParams: { shaderParams: true } };
        const light = { _type: LIGHTTYPE_DIRECTIONAL, _shadowType: SHADOW_PCF3_32F };
        return { device, renderer, sr, camera, light };
    }

    test('draws a caster and updates the draw counters', () => {
        const { device, renderer, sr, camera, light } = setup();
        const caster = createSubmitCaster();

        sr.submitCasters([caster], light, camera);

        expect(caster.ensureMaterial).toHaveBeenCalledWith(device);
        expect(caster.material.prepareForRender).toHaveBeenCalledWith(device, renderer.scene);
        expect(caster.material.setParameters).toHaveBeenCalledWith(device);
        expect(renderer.setupMaterialBindGroup).toHaveBeenCalledWith(caster.material);
        expect(renderer.alphaTestId.setValue).toHaveBeenCalledWith(0.25);
        expect(renderer.setupCullModeAndFrontFace).toHaveBeenCalledWith(true, 1, caster);
        expect(caster.setParameters).toHaveBeenCalledWith(device);
        expect(caster.getShaderInstance).toHaveBeenCalledWith(
            expect.any(Number), expect.anything(), renderer.scene, camera.shaderParams, null
        );
        expect(device.setShader).toHaveBeenCalledWith(caster.shader);
        expect(renderer.setupViewBindGroup).toHaveBeenCalledWith(caster.shader);
        expect(renderer.setVertexBuffers).toHaveBeenCalledWith(device, caster.mesh);
        expect(device.setVertexBuffer).toHaveBeenCalledWith('instance-buffer');
        expect(renderer.setMeshInstanceMatrices).toHaveBeenCalledWith(caster);
        expect(renderer.setupMeshUniformBuffers).toHaveBeenCalledTimes(1);
        expect(device.draw).toHaveBeenCalledWith(7, 'index-buffer', 2, null, true, true, 0);
        expect(renderer.normalMatrixId.setValue).toHaveBeenCalledWith(Mat3.IDENTITY.data);
        expect(renderer._shadowDrawCalls).toBe(1);
        expect(renderer._instancedDrawCalls).toBe(1);
        expect(device.pushMarker).toHaveBeenCalledWith('Node: node, Material: material');
        expect(device.popMarker).toHaveBeenCalled();
    });

    test('flips the front face when the shadow map is flipped', () => {
        const { renderer, sr, camera, light } = setup();
        camera.renderTarget.flipY = true;
        const caster = createSubmitCaster();

        sr.submitCasters([caster], light, camera);

        expect(renderer.setupCullModeAndFrontFace).toHaveBeenCalledWith(true, -1, caster);
    });

    test('skips zero-instance casters without indirect draw commands', () => {
        const { device, renderer, sr, camera, light } = setup();
        const skipped = createSubmitCaster({ caster: { instancingData: { count: 0, vertexBuffer: 'vb' } } });
        const drawn = createSubmitCaster();

        sr.submitCasters([skipped, drawn], light, camera);

        expect(skipped.ensureMaterial).not.toHaveBeenCalled();
        expect(drawn.ensureMaterial).toHaveBeenCalled();
        expect(device.draw).toHaveBeenCalledTimes(1);
        expect(renderer._shadowDrawCalls).toBe(1);
    });

    test('draws zero-instance casters when indirect draw commands exist', () => {
        const { device, sr, camera, light } = setup();
        const indirect = [{ count: 5 }];
        const caster = createSubmitCaster({
            caster: {
                instancingData: { count: 0, vertexBuffer: 'vb' },
                getDrawCommands: jest.fn(() => indirect)
            }
        });

        sr.submitCasters([caster], light, camera);

        expect(device.draw).toHaveBeenCalledWith(7, 'index-buffer', 0, indirect, true, true, 0);
    });

    test('does not bind an instancing buffer when not instanced', () => {
        const { device, sr, camera, light } = setup();
        const caster = createSubmitCaster({ caster: { instancingData: null } });

        sr.submitCasters([caster], light, camera);

        expect(device.setVertexBuffer).not.toHaveBeenCalled();
        expect(device.draw).toHaveBeenCalledWith(7, 'index-buffer', undefined, null, true, true, 0);
    });

    test('prepares a material once and restores overrides when it repeats', () => {
        const { renderer, sr, camera, light } = setup();
        const material = { name: 'shared', alphaTest: 0, parameters: {}, prepareForRender: jest.fn(), setParameters: jest.fn() };
        const first = createSubmitCaster({ material });
        const second = createSubmitCaster({ material });

        sr.submitCasters([first, second], light, camera);

        expect(material.prepareForRender).toHaveBeenCalledTimes(1);
        expect(renderer.setupMaterialBindGroup).toHaveBeenCalledTimes(1);
        expect(renderer.restoreMaterialOverrides).toHaveBeenCalledWith(first, material);
    });

    test('prepares each material when the material changes between casters', () => {
        const { renderer, sr, camera, light } = setup();
        const first = createSubmitCaster();
        const second = createSubmitCaster();

        sr.submitCasters([first, second], light, camera);

        expect(first.material.prepareForRender).toHaveBeenCalledTimes(1);
        expect(second.material.prepareForRender).toHaveBeenCalledTimes(1);
        expect(renderer.restoreMaterialOverrides).not.toHaveBeenCalled();
    });

    test('sets up override bind groups when required', () => {
        const { renderer, sr, camera, light } = setup();
        renderer.needsMaterialOverrideBindGroup.mockReturnValue(true);
        const caster = createSubmitCaster();

        sr.submitCasters([caster], light, camera);

        expect(renderer.setupMaterialOverrideBindGroup).toHaveBeenCalledWith(caster);
    });

    test('uses the mesh instance storage slot for shaders that need it', () => {
        const { device, renderer, sr, camera, light } = setup();
        const caster = createSubmitCaster({ shader: { usesMeshInstanceStorage: true } });

        sr.submitCasters([caster], light, camera);

        expect(renderer.updateStorageSlot).toHaveBeenCalledWith(caster, caster.shader);
        expect(device.draw).toHaveBeenCalledWith(7, 'index-buffer', 2, null, true, true, 3);
    });

    test('skips casters whose shadow shader failed and restores their parameters', () => {
        const { device, renderer, sr, camera, light } = setup();
        const caster = createSubmitCaster({
            shader: { failed: true },
            caster: { _scopeParameters: [{ name: 'custom' }] }
        });

        sr.submitCasters([caster], light, camera);

        expect(device.draw).not.toHaveBeenCalled();
        expect(caster.restoreReplacedParameters).toHaveBeenCalledWith(caster.material);
        expect(renderer._shadowDrawCalls).toBe(0);
        expect(device.popMarker).toHaveBeenCalled();
    });

    test('restores replaced parameters after a successful draw', () => {
        const { sr, camera, light } = setup();
        const caster = createSubmitCaster({ caster: { _scopeParameters: [{ name: 'custom' }] } });

        sr.submitCasters([caster], light, camera);

        expect(caster.restoreReplacedParameters).toHaveBeenCalledWith(caster.material);
    });

    test('warns once about a shader reading the normal matrix in the shadow pass', () => {
        const warnSpy = jest.spyOn(Debug, 'warnOnce').mockImplementation(() => {});
        const { sr, camera, light } = setup();
        const caster = createSubmitCaster({
            shader: { debugReadsUniform: jest.fn(() => true), _debugNormalMatrixChecked: false }
        });
        const second = createSubmitCaster({
            shader: { debugReadsUniform: jest.fn(() => true), _debugNormalMatrixChecked: true }
        });

        sr.submitCasters([caster, second], light, camera);

        expect(warnSpy).toHaveBeenCalledTimes(1);
        expect(warnSpy.mock.calls[0][0]).toContain('matrix_normal');
        expect(caster.shader._debugNormalMatrixChecked).toBe(true);
    });

    test('does not increment the instanced counter for non-instanced draws', () => {
        const { renderer, sr, camera, light } = setup();
        const caster = createSubmitCaster({ caster: { instancingData: null } });

        sr.submitCasters([caster], light, camera);

        expect(renderer._shadowDrawCalls).toBe(1);
        expect(renderer._instancedDrawCalls).toBe(0);
    });
});

