            device.isWebGPU = true;
            device.hasTranspilers = true;

            const shader = new LitShader(device, new LitShaderOptions(), false);
            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
        });

        it('uses GLSL on WebGPU when custom chunks only override GLSL', () => {
            device.isWebGPU = true;
            device.hasTranspilers = true;

            const chunks = new ShaderChunks();
            chunks.glsl.set('customVS', 'void main() {}');

            const shader = new LitShader(device, makeOptions((o) => {
                o.shaderChunks = chunks;
