            expect(shader.chunks.get('usesBuiltinsVS')).toContain('vertex_normal');
            expect(shader.chunks.get('plainVS')).toBe('void main() {}');
        });

        it('copies engine chunks and does not observe later engine changes', () => {
            const engineChunks = ShaderChunks.get(device, SHADERLANGUAGE_GLSL);
            engineChunks.set('engineOnlyVS', 'engine code');

            const shader = makeShader();
            expect(shader.chunks.get('engineOnlyVS')).toBe('engine code');

            engineChunks.set('engineOnlyVS', 'changed code');
            expect(shader.chunks.get('engineOnlyVS')).toBe('engine code');
        });

        it('lets user chunks override engine chunks', () => {
            const engineChunks = ShaderChunks.get(device, SHADERLANGUAGE_GLSL);
            engineChunks.set('sharedVS', 'engine code');

            const chunks = new ShaderChunks();
            chunks.glsl.set('sharedVS', 'user code');

            const shader = makeShader((o) => {
                o.shaderChunks = chunks;
            });
            expect(shader.chunks.get('sharedVS')).toBe('user code');
