        it('uses scene environment uniform names and encoding decode functions', () => {
            const shader = makeShader((o) => {
                o.useSceneEnv = true;
                o.reflectionEncoding = 'rgbm';
                o.reflectionCubemapEncoding = 'xy';
                o.ambientEncoding = 'srgb';
            });
            forwardFragment(shader, 'vUv2_0');

            expect(shader.fDefines.get('{lightingUv}')).toBe('vUv2_0');
            expect(shader.fDefines.get('{reflectionDecode}')).toBe('decodeRGBM');
            expect(shader.fDefines.get('{reflectionCubemapDecode}')).toBe('unpackNormalXY');
            expect(shader.fDefines.get('{ambientDecode}')).toBe('decodeGamma');
            expect(shader.fDefines.get('{LIT_ENV_ATLAS}')).toBe('scene_envAtlas');
            expect(shader.fDefines.get('{LIT_ENV_CUBEMAP}')).toBe('scene_skybox');
        });

        it('maps enum option values to their shader define names', () => {
            const shader = makeShader((o) => {
                o.fresnelModel = FRESNEL_SCHLICK;
                o.nineSlicedMode = SPRITE_RENDERMODE_TILED;
                o.blendType = BLEND_NORMAL;
                o.cubeMapProjection = CUBEPROJ_BOX;
                o.occludeSpecular = SPECOCC_AO;
                o.reflectionSource = REFLECTIONSRC_ENVATLAS;
                o.ambientSource = AMBIENTSRC_ENVALATLAS;
            });
            forwardFragment(shader);

            expect(shader.fDefines.get('LIT_FRESNEL_MODEL')).toBe('SCHLICK');
            expect(shader.fDefines.get('LIT_NONE_SLICE_MODE')).toBe('TILED');
            expect(shader.fDefines.get('LIT_BLEND_TYPE')).toBe('NORMAL');
            expect(shader.fDefines.get('LIT_CUBEMAP_PROJECTION')).toBe('BOX');
            expect(shader.fDefines.get('LIT_OCCLUDE_SPECULAR')).toBe('AO');
            expect(shader.fDefines.get('LIT_REFLECTION_SOURCE')).toBe('ENVATLAS');
            expect(shader.fDefines.get('LIT_AMBIENT_SOURCE')).toBe('ENVALATLAS');
        });
    });

    describe('lighting defines', () => {
        it('reports LIGHT_COUNT and only uses clustered defines when clustered lighting is on', () => {
            const plain = makeShader((o) => {
                o.lights = [makeLight(LIGHTTYPE_DIRECTIONAL)];
            });
            forwardFragment(plain);
            expect(plain.fDefines.get('LIGHT_COUNT')).toBe(1);
            expect(plain.fDefines.has('LIT_CLUSTERED_LIGHTS')).toBe(false);

            const clustered = new LitShader(device, new LitShaderOptions());
            forwardFragment(clustered);
            expect(clustered.fDefines.get('LIGHT_COUNT')).toBe(0);
            expect(clustered.fDefines.get('LIT_CLUSTERED_LIGHTS')).toBe(true);
            expect(clustered.fDefines.has('CLUSTER_COOKIES')).toBe(false);
            expect(clustered.fDefines.has('CLUSTER_AREALIGHTS')).toBe(false);
            expect(clustered.fDefines.has('CLUSTER_MESH_DYNAMIC_LIGHTS')).toBe(false);
            expect(clustered.fDefines.has('CLUSTER_SHADOWS')).toBe(false);
        });

        it('adds clustered lighting feature defines for all enabled options', () => {
            const options = new LitShaderOptions();
            options.clusteredLightingEnabled = true;
            options.clusteredLightingCookiesEnabled = true;
            options.clusteredLightingAreaLightsEnabled = true;
            options.clusteredLightingShadowsEnabled = true;
            options.clusteredLightingShadowType = SHADOW_VSM_16F;
            options.lightMaskDynamic = 0x1;
            options.lights = [makeLight(LIGHTTYPE_DIRECTIONAL)];

            const shader = new LitShader(device, options);
            forwardFragment(shader);

            expect(shader.fDefines.get('LIT_CLUSTERED_LIGHTS')).toBe(true);
            expect(shader.fDefines.get('CLUSTER_COOKIES')).toBe(true);
            expect(shader.fDefines.get('CLUSTER_AREALIGHTS')).toBe(true);
            expect(shader.fDefines.get('CLUSTER_MESH_DYNAMIC_LIGHTS')).toBe(true);
            expect(shader.fDefines.get('CLUSTER_SHADOWS')).toBe(true);
            expect(shader.fDefines.get('SHADOW_KIND_VSM')).toBe(true);
            expect(shader.fDefines.get('CLUSTER_SHADOW_TYPE_VSM')).toBe(true);
            // clustered area lights imply area-light code
            expect(shader.fDefines.get('AREA_LIGHTS')).toBe(true);
            expect(shader.fDefines.get('LIT_CLUSTERED_AREA_LIGHTS')).toBe('');
            expect(shader.fDefines.get('LIT_CLUSTERED_SHADOWS')).toBe('');
        });

        it('suppresses clustered shadows when noShadow is set', () => {
            const options = new LitShaderOptions();
            options.clusteredLightingEnabled = true;
            options.clusteredLightingShadowsEnabled = true;
            options.clusteredLightingShadowType = SHADOW_VSM_16F;
            options.noShadow = true;

            const shader = new LitShader(device, options);
            forwardFragment(shader);

            expect(shader.fDefines.has('CLUSTER_SHADOWS')).toBe(false);
            expect(shader.fDefines.has('SHADOW_KIND_VSM')).toBe(false);
            expect(shader.fDefines.has('CLUSTER_SHADOW_TYPE_VSM')).toBe(false);
        });

        it('emits per-light defines only for directional lights under clustered lighting', () => {
            const options = new LitShaderOptions();
            options.clusteredLightingEnabled = true;
            options.lights = [
                makeLight(LIGHTTYPE_DIRECTIONAL),
                makeLight(LIGHTTYPE_OMNI)
            ];

            const shader = new LitShader(device, options);
            forwardFragment(shader);

            expect(shader.fDefines.get('LIGHT_COUNT')).toBe(2);
            expect(shader.fDefines.get('LIGHT0')).toBe(true);
            expect(shader.fDefines.get('LIGHT0TYPE')).toBe('DIRECTIONAL');
            expect(shader.fDefines.has('LIGHT1')).toBe(false);
            expect(shader.fDefines.has('LIGHT1TYPE')).toBe(false);
        });

        it('emits directional light shadow defines including cascades', () => {
            const shader = makeShader((o) => {
                o.lights = [makeLight(LIGHTTYPE_DIRECTIONAL, {
                    castShadows: true,
                    _normalOffsetBias: 1,
                    usesCascadeBlend: true,
                    shadowCascadeCount: 2,
                    affectSpecularity: true
                })];
            });
            forwardFragment(shader);

            expect(shader.fDefines.get('LIGHT0')).toBe(true);
            expect(shader.fDefines.get('LIGHT0TYPE')).toBe('DIRECTIONAL');
            expect(shader.fDefines.get('LIGHT0SHADOWTYPE')).toBe('PCF3_32F');
            expect(shader.fDefines.get('LIGHT0SHAPE')).toBe('PUNCTUAL');
            expect(shader.fDefines.get('LIGHT0FALLOFF')).toBe('LINEAR');
            expect(shader.fDefines.get('LIGHT0AFFECT_SPECULARITY')).toBe(true);
            expect(shader.fDefines.get('LIGHT0CASTSHADOW')).toBe(true);
            expect(shader.fDefines.get('LIGHT0SHADOW_PCF')).toBe(true);
            expect(shader.fDefines.get('LIGHT0_SHADOW_SAMPLE_NORMAL_OFFSET')).toBe(true);
            expect(shader.fDefines.get('LIGHT0_SHADOW_SAMPLE_ORTHO')).toBe(true);
            expect(shader.fDefines.get('LIGHT0_SHADOW_CASCADE_BLEND')).toBe(true);
            expect(shader.fDefines.get('LIGHT0_SHADOW_CASCADES')).toBe(true);
            expect(shader.fDefines.get('LIGHT0_SHADOW_SAMPLE_SOURCE_ZBUFFER')).toBe(true);
            expect(shader.fDefines.get('SHADOW_KIND_PCF3')).toBe(true);
            expect(shader.fDefines.get('SHADOW_DIRECTIONAL')).toBe(true);
        });

        it('suppresses per-light shadow defines when noShadow is set', () => {
            const shader = makeShader((o) => {
                o.noShadow = true;
                o.lights = [makeLight(LIGHTTYPE_DIRECTIONAL, { castShadows: true })];
            });
            forwardFragment(shader);

            expect(shader.fDefines.has('LIGHT0CASTSHADOW')).toBe(false);
            expect(shader.fDefines.has('SHADOW_KIND_PCF3')).toBe(false);
            expect(shader.fDefines.has('SHADOW_DIRECTIONAL')).toBe(false);
        });

        it('emits omni cookie and VSM point-shadow defines', () => {
            const shader = makeShader((o) => {
                o.lights = [makeLight(LIGHTTYPE_OMNI, {
                    castShadows: true,
                    _shadowType: SHADOW_VSM_16F,
                    _isVsm: true,
                    _normalOffsetBias: 1,
                    _cookie: { _cubemap: true },
                    _cookieChannel: 'rgb'
                })];
            });
            forwardFragment(shader);

            expect(shader.fDefines.get('LIGHT0TYPE')).toBe('OMNI');
            expect(shader.fDefines.get('LIGHT0SHADOWTYPE')).toBe('VSM_16F');
            expect(shader.fDefines.get('LIGHT0COOKIE')).toBe(true);
            expect(shader.fDefines.get('{LIGHT0COOKIE_CHANNEL}')).toBe('rgb');
            expect(shader.fDefines.get('LIGHT0CASTSHADOW')).toBe(true);
            expect(shader.fDefines.get('LIGHT0_SHADOW_SAMPLE_POINT')).toBe(true);
            expect(shader.fDefines.get('SHADOW_KIND_VSM')).toBe(true);
            // VSM does not use PCF or the z-buffer path on a non-WebGPU device
            expect(shader.fDefines.has('LIGHT0SHADOW_PCF')).toBe(false);
            expect(shader.fDefines.has('LIGHT0_SHADOW_SAMPLE_NORMAL_OFFSET')).toBe(false);
            expect(shader.fDefines.has('LIGHT0_SHADOW_SAMPLE_SOURCE_ZBUFFER')).toBe(false);
        });

        it('emits spot cookie transform/falloff and PCSS z-buffer defines', () => {
            const shader = makeShader((o) => {
                o.lights = [makeLight(LIGHTTYPE_SPOT, {
                    castShadows: true,
                    _shadowType: SHADOW_PCSS_32F,
                    _falloffMode: LIGHTFALLOFF_INVERSESQUARED,
                    _cookie: { _cubemap: false },
                    _cookieChannel: 'r',
                    _cookieTransform: true,
                    _cookieFalloff: true
                })];
            });
            forwardFragment(shader);

            expect(shader.fDefines.get('LIGHT0TYPE')).toBe('SPOT');
            expect(shader.fDefines.get('LIGHT0FALLOFF')).toBe('INVERSESQUARED');
            expect(shader.fDefines.get('LIGHT0COOKIE')).toBe(true);
            expect(shader.fDefines.get('{LIGHT0COOKIE_CHANNEL}')).toBe('r');
            expect(shader.fDefines.get('LIGHT0COOKIE_TRANSFORM')).toBe(true);
            expect(shader.fDefines.get('LIGHT0COOKIE_FALLOFF')).toBe(true);
            expect(shader.fDefines.get('LIGHT0_SHADOW_SAMPLE_SOURCE_ZBUFFER')).toBe(true);
            expect(shader.fDefines.get('SHADOW_KIND_PCSS')).toBe(true);
            expect(shader.fDefines.has('LIGHT0_SHADOW_SAMPLE_ORTHO')).toBe(false);
            expect(shader.fDefines.has('LIGHT0_SHADOW_SAMPLE_POINT')).toBe(false);
        });

        it('does not emit cookie defines for incompatible light/cookie combinations', () => {
            const shader = makeShader((o) => {
                o.lights = [
                    makeLight(LIGHTTYPE_SPOT, { _cookie: { _cubemap: true }, _cookieChannel: 'rgb' }),
                    makeLight(LIGHTTYPE_OMNI, { _cookie: { _cubemap: false }, _cookieChannel: 'rgb' }),
                    makeLight(LIGHTTYPE_DIRECTIONAL, { _cookie: { _cubemap: true }, _cookieChannel: 'rgb' })
                ];
            });
            forwardFragment(shader);

            expect(shader.fDefines.has('LIGHT0COOKIE')).toBe(false);
            expect(shader.fDefines.has('LIGHT1COOKIE')).toBe(false);
            expect(shader.fDefines.has('LIGHT2COOKIE')).toBe(false);
        });

        it('enables area lights from light shapes and maps their shape names', () => {
            const shader = makeShader((o) => {
                o.lights = [
                    makeLight(LIGHTTYPE_DIRECTIONAL, { _shape: LIGHTSHAPE_RECT }),
                    makeLight(LIGHTTYPE_OMNI, { _shape: LIGHTSHAPE_PUNCTUAL })
                ];
            });
            forwardFragment(shader);

            expect(shader.fDefines.get('AREA_LIGHTS')).toBe(true);
            expect(shader.fDefines.get('LIGHT0SHAPE')).toBe('RECT');
            expect(shader.fDefines.get('LIGHT1SHAPE')).toBe('PUNCTUAL');
        });

        it('adds z-buffer shadow sampling define on WebGPU', () => {
            device.isWebGPU = true;
            device.hasTranspilers = true;

            const shader = makeShader((o) => {
                o.lights = [makeLight(LIGHTTYPE_OMNI, {
                    castShadows: true,
                    _shadowType: SHADOW_VSM_16F,
                    _isVsm: true
                })];
            });
            forwardFragment(shader);

            expect(shader.fDefines.get('LIGHT0_SHADOW_SAMPLE_SOURCE_ZBUFFER')).toBe(true);
        });
    });
});
